UPDATE content_items SET draft_json=json_set(draft_json,'$.title',json_extract('{"v":"Custom Sign Manufacturing for the Trade"}','$.v')),published_json=json_set(published_json,'$.title',json_extract('{"v":"Custom Sign Manufacturing for the Trade"}','$.v')),version=version+1 WHERE slug='for-sign-companies' AND type='page' AND status='published' AND json_extract(draft_json,'$.title')=json_extract('{"v":"Custom Sign Fabrication for Sign Companies & Installers"}','$.v') AND json_extract(published_json,'$.title')=json_extract('{"v":"Custom Sign Fabrication for Sign Companies & Installers"}','$.v');

UPDATE content_items SET draft_json=json_set(draft_json,'$.intro',json_extract('{"v":"Custom illuminated letters, metal logos and commercial signage, made to your artwork and project specifications."}','$.v')),published_json=json_set(published_json,'$.intro',json_extract('{"v":"Custom illuminated letters, metal logos and commercial signage, made to your artwork and project specifications."}','$.v')),version=version+1 WHERE slug='for-sign-companies' AND type='page' AND status='published' AND json_extract(draft_json,'$.intro')=json_extract('{"v":"Sourcing custom lettering or illuminated signs for a customer project? We coordinate with manufacturing partners to review your specifications and prepare a project-based supply quote."}','$.v') AND json_extract(published_json,'$.intro')=json_extract('{"v":"Sourcing custom lettering or illuminated signs for a customer project? We coordinate with manufacturing partners to review your specifications and prepare a project-based supply quote."}','$.v');

UPDATE content_items SET draft_json=json_set(draft_json,'$.body',json_extract('{"v":"## Signs for Your Next Customer Project.\n\nWe make custom illuminated letters, metal lettering, acrylic logos and commercial signs around your artwork, dimensions and installation requirements.\n\n## From Artwork to an Agreed Specification\n\nShare your drawings, overall dimensions, quantities and destination. We review materials, finish, lighting, mounting and delivery before production approval. Preliminary files are welcome.\n\n## Production and Order Checks\n\nWe confirm the appearance, construction, lighting and packing check points for your order. Required inspection records, documentation and installation aids are included where agreed in your quotation.\n\n## Project and Repeat Orders\n\nFor repeat or multi-site requirements, identify the approved design reference, quantities by location and any differences in size or fixing. We review schedules, labelling and shipment arrangements for the project.\n\n## Start Your Trade Enquiry\n\nSign in to share your artwork, approximate dimensions, quantity, delivery destination and target date. We will follow up to clarify the details and prepare your project quote."}','$.v')),published_json=json_set(published_json,'$.body',json_extract('{"v":"## Signs for Your Next Customer Project.\n\nWe make custom illuminated letters, metal lettering, acrylic logos and commercial signs around your artwork, dimensions and installation requirements.\n\n## From Artwork to an Agreed Specification\n\nShare your drawings, overall dimensions, quantities and destination. We review materials, finish, lighting, mounting and delivery before production approval. Preliminary files are welcome.\n\n## Production and Order Checks\n\nWe confirm the appearance, construction, lighting and packing check points for your order. Required inspection records, documentation and installation aids are included where agreed in your quotation.\n\n## Project and Repeat Orders\n\nFor repeat or multi-site requirements, identify the approved design reference, quantities by location and any differences in size or fixing. We review schedules, labelling and shipment arrangements for the project.\n\n## Start Your Trade Enquiry\n\nSign in to share your artwork, approximate dimensions, quantity, delivery destination and target date. We will follow up to clarify the details and prepare your project quote."}','$.v')),version=version+1 WHERE slug='for-sign-companies' AND type='page' AND status='published' AND json_extract(draft_json,'$.body')=json_extract('{"v":"## Fabrication Support for Your Customer Projects\n\nThis enquiry route is for sign companies, installers, fit-out contractors and procurement teams reviewing a custom sign supply requirement. Start with the specification you have; open technical questions can be clarified before a production-ready scope is approved.\n\n## Prepare the Brief in Four Parts\n\n### Artwork and Dimensions\n\nShare vector artwork or drawings where available, overall and individual letter sizes, quantities and any tolerances that your project requires. Identify provisional measurements and the person responsible for final approval.\n\n### Materials, Finishes and Lighting\n\nSpecify the material or visual reference, face and side appearance, illuminated or unlit effect, and any colour approval requirement. Identify destination-specific electrical requirements and supporting documents at the enquiry stage.\n\n### Mounting and Site Coordination\n\nTell us the mounting surface, proposed fixing method, cable access and the local installation team''s requirements. Agree which drawings, fixing parts or layout aids are included and which site work remains with the local contractor.\n\n### Packing and Delivery\n\nConfirm the number of signs, destination, handling requirements, labelling and whether items need to be grouped by installation location. Shipping scope, import responsibilities and timing must be agreed in the quotation.\n\n## Agree the Review and Approval Points\n\nDiscuss drawing review, finish or lighting samples where needed, production approval and the checks or records required before dispatch. These are project arrangements to confirm, not services automatically included with every enquiry.\n\n## Repeat or Multi-site Requirements\n\nIf consistency across several signs matters, identify the approved master reference, quantities by location and which dimensions or details may vary. Repeat supply, schedule, packaging and commercial terms are reviewed for the actual requirement; no standing capacity commitment is implied.\n\n## Production References\n\nThe supplier photographs below illustrate equipment and fabrication activity. They do not establish a verified tolerance, certification or production rate. Ask about the actual construction and evidence needed for your project.\n\n## Questions for Trade Buyers\n\n### Can I start with a preliminary drawing?\n\nYes. Mark undecided dimensions or details so they can be reviewed before quotation assumptions become production instructions.\n\n### Do you provide local installation?\n\nDo not assume it is included. Agree fabrication, supplied parts, documentation, shipping, site access and local installation responsibilities separately.\n\n### Are certificates or inspection records included?\n\nState your requirements before quoting. Document availability and applicability must be checked for the actual product, destination and scope."}','$.v') AND json_extract(published_json,'$.body')=json_extract('{"v":"## Fabrication Support for Your Customer Projects\n\nThis enquiry route is for sign companies, installers, fit-out contractors and procurement teams reviewing a custom sign supply requirement. Start with the specification you have; open technical questions can be clarified before a production-ready scope is approved.\n\n## Prepare the Brief in Four Parts\n\n### Artwork and Dimensions\n\nShare vector artwork or drawings where available, overall and individual letter sizes, quantities and any tolerances that your project requires. Identify provisional measurements and the person responsible for final approval.\n\n### Materials, Finishes and Lighting\n\nSpecify the material or visual reference, face and side appearance, illuminated or unlit effect, and any colour approval requirement. Identify destination-specific electrical requirements and supporting documents at the enquiry stage.\n\n### Mounting and Site Coordination\n\nTell us the mounting surface, proposed fixing method, cable access and the local installation team''s requirements. Agree which drawings, fixing parts or layout aids are included and which site work remains with the local contractor.\n\n### Packing and Delivery\n\nConfirm the number of signs, destination, handling requirements, labelling and whether items need to be grouped by installation location. Shipping scope, import responsibilities and timing must be agreed in the quotation.\n\n## Agree the Review and Approval Points\n\nDiscuss drawing review, finish or lighting samples where needed, production approval and the checks or records required before dispatch. These are project arrangements to confirm, not services automatically included with every enquiry.\n\n## Repeat or Multi-site Requirements\n\nIf consistency across several signs matters, identify the approved master reference, quantities by location and which dimensions or details may vary. Repeat supply, schedule, packaging and commercial terms are reviewed for the actual requirement; no standing capacity commitment is implied.\n\n## Production References\n\nThe supplier photographs below illustrate equipment and fabrication activity. They do not establish a verified tolerance, certification or production rate. Ask about the actual construction and evidence needed for your project.\n\n## Questions for Trade Buyers\n\n### Can I start with a preliminary drawing?\n\nYes. Mark undecided dimensions or details so they can be reviewed before quotation assumptions become production instructions.\n\n### Do you provide local installation?\n\nDo not assume it is included. Agree fabrication, supplied parts, documentation, shipping, site access and local installation responsibilities separately.\n\n### Are certificates or inspection records included?\n\nState your requirements before quoting. Document availability and applicability must be checked for the actual product, destination and scope."}','$.v');

