UPDATE content_items SET draft_json=json_set(draft_json,'$.intro',json_extract('{"v":"Custom Sign Forge supplies custom illuminated letters, metal logos and commercial signage made to your artwork, space and project requirements."}','$.v')),published_json=json_set(published_json,'$.intro',json_extract('{"v":"Custom Sign Forge supplies custom illuminated letters, metal logos and commercial signage made to your artwork, space and project requirements."}','$.v')),version=version+1 WHERE slug='about' AND type='page' AND status='published' AND json_extract(draft_json,'$.intro')=json_extract('{"v":"Custom Sign Forge works with manufacturing partners to supply custom business signs, illuminated lettering and dimensional signs for overseas projects."}','$.v') AND json_extract(published_json,'$.intro')=json_extract('{"v":"Custom Sign Forge works with manufacturing partners to supply custom business signs, illuminated lettering and dimensional signs for overseas projects."}','$.v');

UPDATE content_items SET draft_json=json_set(draft_json,'$.body',json_extract('{"v":"## Made Around Your Brand.\n\nWe turn logos, lettering and reference ideas into custom signs for shops, offices, hospitality spaces and commercial projects. Our focus is a clear specification, considered construction and a finished sign that fits its setting.\n\n## From Your Artwork to Production\n\nWe review your logo, dimensions, material, finish, lighting and mounting requirements with you. The quotation identifies the supplied items, price and delivery arrangements. Final drawings and open details are confirmed before production begins.\n\n## The Details Behind the Sign\n\nExplore metal construction, illuminated lettering and fabrication details. We review the appearance, order checks and packing requirements against the approved specification. Any requested inspection records, finish references or installation aids are confirmed for the order.\n\n## For Business Owners and the Trade\n\nWe welcome individual business projects, sign companies, installers and design teams. Share your intended use, quantity and destination so we can review the right fabrication approach for your project.\n\n## Start with What You Know\n\nA logo, a reference photo or approximate dimensions are enough to begin the conversation. Sign in to send your project details and files, then discuss the specification and quote with us."}','$.v')),published_json=json_set(published_json,'$.body',json_extract('{"v":"## Made Around Your Brand.\n\nWe turn logos, lettering and reference ideas into custom signs for shops, offices, hospitality spaces and commercial projects. Our focus is a clear specification, considered construction and a finished sign that fits its setting.\n\n## From Your Artwork to Production\n\nWe review your logo, dimensions, material, finish, lighting and mounting requirements with you. The quotation identifies the supplied items, price and delivery arrangements. Final drawings and open details are confirmed before production begins.\n\n## The Details Behind the Sign\n\nExplore metal construction, illuminated lettering and fabrication details. We review the appearance, order checks and packing requirements against the approved specification. Any requested inspection records, finish references or installation aids are confirmed for the order.\n\n## For Business Owners and the Trade\n\nWe welcome individual business projects, sign companies, installers and design teams. Share your intended use, quantity and destination so we can review the right fabrication approach for your project.\n\n## Start with What You Know\n\nA logo, a reference photo or approximate dimensions are enough to begin the conversation. Sign in to send your project details and files, then discuss the specification and quote with us."}','$.v')),version=version+1 WHERE slug='about' AND type='page' AND status='published' AND json_extract(draft_json,'$.body')=json_extract('{"v":"## Custom Signs Through Project Coordination\n\nCustom Sign Forge helps overseas business owners, sign companies and installers discuss custom lettering and signage with manufacturing partners. Our role is to coordinate the enquiry, clarify open requirements and bring the agreed supply scope into the quotation and order documents.\n\n## Our Role and the Manufacturing Partner''s Role\n\nWe handle project communication and coordinate the proposed construction, finish, lighting and delivery requirements with production partners. We do not present a partner''s premises or equipment as our own factory. The seller, supplied items and responsibilities for a particular order are identified in its quotation and order documents.\n\n## From a Reference to an Agreed Specification\n\nYou can start with a logo, photograph or initial idea. We review dimensions, materials, lighting, quantities, destination and installation requirements before the project is treated as ready for production. Approval points and any remaining assumptions should be clear in writing.\n\n## What the Images Show\n\nThe photographs below come from supplier promotional material supplied for this project. They show production references, not a claim about ownership, capacity, certification or a completed Custom Sign Forge customer order. Generated concepts elsewhere on the site are labelled separately.\n\n## Checks, Packing and Delivery\n\nAny agreed appearance checks, lighting review, inspection records, packaging and shipment documents need to be included in the project scope. Availability, responsibility and cost are confirmed per order; we do not publish unverified production volumes, universal delivery times or installation coverage.\n\n## Tell Us About Your Project\n\nShare the sign style, intended use, delivery country and anything you already know about the design. You do not need a final drawing or budget to start. Use the enquiry page to save the initial details and obtain a reference."}','$.v') AND json_extract(published_json,'$.body')=json_extract('{"v":"## Custom Signs Through Project Coordination\n\nCustom Sign Forge helps overseas business owners, sign companies and installers discuss custom lettering and signage with manufacturing partners. Our role is to coordinate the enquiry, clarify open requirements and bring the agreed supply scope into the quotation and order documents.\n\n## Our Role and the Manufacturing Partner''s Role\n\nWe handle project communication and coordinate the proposed construction, finish, lighting and delivery requirements with production partners. We do not present a partner''s premises or equipment as our own factory. The seller, supplied items and responsibilities for a particular order are identified in its quotation and order documents.\n\n## From a Reference to an Agreed Specification\n\nYou can start with a logo, photograph or initial idea. We review dimensions, materials, lighting, quantities, destination and installation requirements before the project is treated as ready for production. Approval points and any remaining assumptions should be clear in writing.\n\n## What the Images Show\n\nThe photographs below come from supplier promotional material supplied for this project. They show production references, not a claim about ownership, capacity, certification or a completed Custom Sign Forge customer order. Generated concepts elsewhere on the site are labelled separately.\n\n## Checks, Packing and Delivery\n\nAny agreed appearance checks, lighting review, inspection records, packaging and shipment documents need to be included in the project scope. Availability, responsibility and cost are confirmed per order; we do not publish unverified production volumes, universal delivery times or installation coverage.\n\n## Tell Us About Your Project\n\nShare the sign style, intended use, delivery country and anything you already know about the design. You do not need a final drawing or budget to start. Use the enquiry page to save the initial details and obtain a reference."}','$.v');

