UPDATE site_settings SET value_json=json_set(value_json,'$.businessDescription',json_extract('{"v":"Custom business signs, illuminated letters and dimensional lettering, made to your project specifications. We welcome enquiries from Southeast Asia, Europe and North America. Pricing and delivery are confirmed for each order."}','$.v')),version=version+1 WHERE id=1 AND json_extract(value_json,'$.businessDescription')=json_extract('{"v":"Custom business signs, illuminated letters and dimensional lettering, supplied through manufacturing partners. We welcome project enquiries for Southeast Asia, Europe and North America. Specifications, price and delivery arrangements are confirmed individually."}','$.v');
